package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalGroupedRounds.*;
import org.kanger.ContextUniversalGroupedRounds.Result;
import org.kanger.ContextUniversalGroupedChainAudit.*;
import org.kanger.ContextWitnessResultTransport.*;

/** One cumulative owning session, separate independent replay, and full legacy semantic controls. */
public final class ContextUniversalGroupedSessionRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    interface Action{void run()throws Exception;}
    static void reject(Action a,String why)throws Exception{boolean no=false;try{a.run();}catch(IllegalArgumentException|IllegalStateException expected){no=true;}require(no,why);}
    static SessionRun run(ContextUniversalGroupedChainAuditRunner.Fixture f,int rounds,int work,int capacity){return ContextUniversalGroupedRounds.runWithValidationReuse(f.x,f.foreign,f.input,f.pools,f.units,f.compounds,f.limits,f.local,rounds,work,capacity);}
    static SessionInspection audit(ContextUniversalGroupedChainAuditRunner.Fixture f,Result r,int work){return ContextUniversalGroupedChainAudit.inspectWithValidationReuse(f.x,f.foreign,f.input,f.pools,f.units,f.compounds,f.limits,f.local,8,r,work,4096);}
    static void incomplete(SessionRun s,int completed){Result r=s.result;require(r.status==Status.INCOMPLETE&&r.completedRounds==completed&&r.output==null&&r.symbolicOutput==null&&r.compoundOutput==null&&r.history.isEmpty()&&r.refutations.isEmpty(),r.phase+": "+r.reason);require(s.metrics.entries==0,"failed owning invocation retains no memo frames");}
    static Receipt yes(SessionInspection s){require(s.inspection.audited&&s.inspection.output!=null,s.inspection.phase+": "+s.inspection.reason);require(s.metrics.entries==0&&s.metrics.verified>0&&s.metrics.hits>0,"independent invocation authenticates fresh frames then closes its own memo");return s.inspection.output;}
    static void no(SessionInspection s,String why){require(!s.inspection.audited&&s.inspection.output==null&&s.metrics.entries==0,why+": "+s.inspection.phase+" "+s.inspection.reason);}
    static void compare(Result a,Result b){require(a.status==Status.STABLE_GROUPED_POOLS&&b.status==a.status&&a.completedRounds==b.completedRounds&&a.history.size()==b.history.size(),b.phase+": "+b.reason);for(int i=0;i<a.history.size();++i){Round p=a.history.get(i),q=b.history.get(i);require(p.number==q.number&&p.commonChanged==q.commonChanged&&p.privateChanged==q.privateChanged&&p.symbolicChanged==q.symbolicChanged&&p.compoundChanged==q.compoundChanged&&p.barrier.localChanged==q.barrier.localChanged,"identical all-round progress flags");require(ContextWitnessResultTransport.sameContents(p.input,q.input,WORK)&&ContextWitnessResultTransport.sameContents(p.barrier.packet,q.barrier.packet,WORK)&&ContextUniversalSignedUnitExchange.sameContents(p.symbolicInput,q.symbolicInput,WORK)&&ContextUniversalSignedUnitExchange.sameContents(p.symbolicOutput,q.symbolicOutput,WORK)&&ContextUniversalCompoundExchange.sameContents(p.compoundInput,q.compoundInput,WORK)&&ContextUniversalCompoundExchange.sameContents(p.compoundOutput,q.compoundOutput,WORK),"all four typed Source/grade barrier contents match legacy");require(p.checks.keySet().equals(q.checks.keySet())&&p.privateInput.keySet().equals(q.privateInput.keySet()),"same actual cut inventory");for(Cut cut:p.checks.keySet())require(ContextUniversalGroupedLocalRounds.sameContents(p.checks.get(cut),q.checks.get(cut),ContextGroundProductionRounds.budget(WORK)),"full actual cut clause/exact-Source/depth pool equality");for(Cut cut:p.privateInput.keySet())require(ContextWitnessResultTransport.sameContents(p.privateInput.get(cut).local,q.privateInput.get(cut).local,WORK)&&ContextWitnessResultTransport.sameContents(p.barrier.privatePools.get(cut).local,q.barrier.privatePools.get(cut).local,WORK),"private incoming/rebased minima unchanged");}}
    static void stableAndBudget()throws Exception {
        ContextUniversalGroupedChainAuditRunner.Fixture f=new ContextUniversalGroupedChainAuditRunner.Fixture(false,false);SessionRun full=run(f,8,WORK,4096);compare(f.trace,full.result);require(full.metrics.entries==0&&full.metrics.hits>0&&full.metrics.peakEntries<=4096,"closed bounded session for complete owning run");yes(audit(f,full.result,WORK));Receipt receipt=yes(audit(f,full.result,WORK));require(ContextUniversalGroupedChainAudit.checkWithValidationReuse(receipt,WORK,4096).verified>0,"receipt recheck creates another independent fresh invocation");no(audit(f,full.result,1),"work1 cannot exploit successful controller/previous audit");
        SessionRun first=run(f,1,WORK,4096);incomplete(first,1);require(first.result.phase.equals("round-limit")&&first.metrics.work<full.metrics.work,"actual completed first-barrier cost observed");int limit=(int)first.metrics.work+1;SessionRun small=run(f,8,limit,4096);incomplete(small,1);require(small.metrics.work==limit+1&&small.result.reason.contains("Ground transport work limit"),"owning work is cumulative across rounds, not reset each round");System.out.println("SESSION_CUMULATIVE first="+first.metrics.work+" full="+full.metrics.work+" limit="+limit+" refusedAt="+small.metrics.work+" phase="+small.result.phase);
        SessionRun bounded=run(f,8,WORK,1);compare(f.trace,bounded.result);require(bounded.metrics.peakEntries==1&&bounded.metrics.capacityBypass>0&&bounded.metrics.entries==0,"bounded-capacity fallback keeps genuine validation");incomplete(run(f,8,1,4096),0);reject(()->run(f,8,WORK,0),"invalid memo capacity");
        Round last=full.result.history.get(full.result.history.size()-1);java.lang.reflect.Field flag=Round.class.getDeclaredField("compoundChanged");flag.setAccessible(true);flag.set(last,true);try{no(audit(f,full.result,WORK),"fresh audit rejects forged terminal stability after earlier successful audit");}finally{flag.set(last,false);}
        java.lang.reflect.Field output=Result.class.getDeclaredField("output");output.setAccessible(true);Object actual=output.get(full.result);output.set(full.result,full.result.history.get(0).barrier);try{no(audit(f,full.result,WORK),"old barrier cannot replace actual terminal output");}finally{output.set(full.result,actual);}
        require(f.input.basis==null&&full.result.output.packet.basis==null&&!full.result.output.packet.observedStep,"scope adds no STEP/admission marker");
    }
    static void symbolic()throws Exception {ContextUniversalGroupedChainAuditRunner.Fixture f=new ContextUniversalGroupedChainAuditRunner.Fixture(true,false);SessionRun s=run(f,8,WORK,4096);compare(f.trace,s.result);require(s.result.history.get(0).symbolicChanged&&!s.result.history.get(0).commonChanged,"symbolic-only progress still forces next qualification");yes(audit(f,s.result,WORK));}
    static void rejection()throws Exception {
        Snapshot x=ContextUniversalGroupedRoundsRunner.bind(true,"!anchor(1); !@u p(u);"),a=ContextUniversalGroupedRoundsRunner.bind(false,"!@u p(u)&&b(u)->r(u);"),b=ContextUniversalGroupedRoundsRunner.bind(false,"!b(1); !~r(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> cuts=Arrays.asList(a,b);ContextUniversalCompoundExchange.Exchange input=ContextUniversalGroupedRoundsRunner.exchange(x,cuts,p,Collections.emptyMap());SessionRun r=ContextUniversalGroupedRounds.runWithValidationReuse(x,cuts,p,Collections.emptyMap(),ContextUniversalGroupedRoundsRunner.units(input),input,ContextUniversalGroupedRoundsRunner.limits(16),ContextUniversalGroupedRoundsRunner.local(),8,WORK,4096);require(r.result.status==Status.REFUTED&&r.result.history.isEmpty()&&r.result.output==null&&r.metrics.entries==0&&!r.result.refutations.isEmpty(),"authenticated refutation still exports no stable product/history prefix");for(Refutation f:r.result.refutations.values())for(ContextUniversalFrozenConstraints.Proof proof:f.proofs){require(proof.clause==null,"empty rejection roots only");ContextUniversalGroupedRoundsRunner.flatten(proof,Collections.newSetFromMap(new IdentityHashMap<ContextUniversalFrozenConstraints.Proof,Boolean>()));}
        Snapshot late=ContextUniversalGroupedRoundsRunner.bind(false,"!$u later(u);");PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,late,WORK);List<Snapshot> all=Arrays.asList(a,b,late);ContextUniversalCompoundExchange.Exchange e=ContextUniversalGroupedRoundsRunner.exchange(x,all,p,Collections.singletonMap(pool.cut,pool));SessionRun failed=ContextUniversalGroupedRounds.runWithValidationReuse(x,all,p,Collections.emptyMap(),ContextUniversalGroupedRoundsRunner.units(e),e,ContextUniversalGroupedRoundsRunner.limits(16),ContextUniversalGroupedRoundsRunner.local(),8,WORK,4096);incomplete(failed,0);require(failed.result.phase.equals("checks"),"late unvalidated cut suppresses earlier real refutation");
    }
    static void privateCase()throws Exception {
        ContextUniversalGroupedChainAuditRunner.Fixture f=new ContextUniversalGroupedChainAuditRunner.Fixture(false,true);SessionRun s=run(f,8,WORK,4096);compare(f.trace,s.result);yes(audit(f,s.result,WORK));require(s.result.output.packet.items.stream().anyMatch(i->i.atom.predicate.equals("r"))&&s.result.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("a")||i.atom.predicate.equals("hidden")),"only proved private-Origin products shared");Cut cut=Cut.of(f.a);PrivatePool branch=s.result.output.branches.get(cut).privateAfter,finalPool=s.result.output.privatePools.get(cut);java.lang.reflect.Field sources=PrivatePool.class.getDeclaredField("sources");sources.setAccessible(true);Object beforeBranch=sources.get(branch),beforeFinal=sources.get(finalPool);sources.set(branch,Collections.emptySet());sources.set(finalPool,Collections.emptySet());try{no(audit(f,s.result,WORK),"joint branch/final Sources forgery remains rejected by independent fresh audit");}finally{sources.set(branch,beforeBranch);sources.set(finalPool,beforeFinal);}
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("grouped-session-").toString());stableAndBudget();symbolic();rejection();privateCase();System.out.println("CONTEXT_UNIVERSAL_GROUPED_SESSION_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
